155	      if (i === mySlot) { s.name = name; if (s.who === 2) { s.who = 0; stHide(i); } continue; }   // slot vừa thành của mình: bỏ người khác cũ, chờ setSelf
156	      if (name === null) { s.name = null; if (s.who === 2) { s.who = 0; stHide(i); } continue; }
157	      if (name !== s.name || ch !== s.ch || s.who !== 2) { s.name = name; s.ch = ch; s.who = 2; stHide(i); }   // đổi chủ (tên hoặc nhân vật khác): gỡ bản sao cũ
