233	const A = CONFIG.stroll.anim, NC = ST_CLIPS.length;
234	const ST_LOCO0 = 1, ST_LOCO1 = 3, ST_PHOTO = 4;   // chỉ số trong ST_CLIPS: walk..sprint, photo (idle = 0)
235	
236	export interface StRigSource {
237	  scene: THREE.Object3D;                                   // cảnh gốc (không thêm vào scene; chỉ để sao chép)
238	  clips: THREE.AnimationClip[];                            // 5 đoạn theo thứ tự ST_CLIPS
239	  natural: Float32Array;                                   // tốc độ tự nhiên từng đoạn theo ST_CLIPS, m/s (idle / photo = 0)
240	  height: number;                                          // chiều cao tư thế đứng, m (0 nếu file không ghi)
241	  clone: (o: THREE.Object3D) => THREE.Object3D;            // SkeletonUtils.clone (test truyền bản giả)
242	}
