244	/* Chuẩn hóa cảnh + đoạn đã nạp thành nguồn dùng chung. speeds: tên đoạn → m/s. Thiếu đoạn nào thì ném lỗi (stRigLoad bắt, trả null) */
245	export function stRigSource(scene: THREE.Object3D, clips: THREE.AnimationClip[], speeds: Record<string, number>, height: number, clone: (o: THREE.Object3D) => THREE.Object3D): StRigSource {
246	  const out: THREE.AnimationClip[] = [], natural = new Float32Array(NC);
247	  for (let i = 0; i < NC; i++) {
248	    const c = clips.find(x => x.name === ST_CLIPS[i]);
249	    if (!c) throw new Error(`thiếu đoạn ${ST_CLIPS[i]}`);
250	    out.push(c);
251	    natural[i] = Math.max(0, Number(speeds[ST_CLIPS[i]]) || 0);
252	  }
253	  scene.traverse((o) => {
254	    o.layers.set(1);
255	    const m = o as THREE.Mesh;
256	    if (!m.isMesh) return;
257	    m.castShadow = false; m.receiveShadow = false; m.frustumCulled = false;
258	    const mats = Array.isArray(m.material) ? m.material : [m.material];
259	    for (const mat of mats) {
260	      const s = mat as THREE.MeshStandardMaterial;
261	      if (s.isMeshStandardMaterial) { s.metalness = 0; s.roughness = 0.85; }
262	      if (s.alphaTest > 0) s.transparent = false;   // MASK: cắt theo alphaTest, không trộn trong suốt (không cần sắp thứ tự)
263	    }
264	  });
265	  return { scene, clips: out, natural, height: height > 0 ? height : 0, clone };
266	}
