270	/* Làm nóng shader (D-018): stroll/index.ts gắn hàm biên dịch sẵn chương trình của cảnh nguồn theo đèn / sương / bóng của cảnh chính
271	   (rig.ts không import renderer để chạy được trong unit test). Chưa gắn, lỗi hoặc quá anim.warmMs: bỏ qua, nguồn vẫn dùng được */
272	let warm: ((o: THREE.Object3D) => Promise<unknown>) | null = null;
273	export function stRigSetWarm(fn: ((o: THREE.Object3D) => Promise<unknown>) | null): void { warm = fn; }
274	async function stRigWarm(o: THREE.Object3D): Promise<void> {
275	  if (!warm) return;
276	  let timer = 0;
277	  try { await Promise.race([warm(o), new Promise<void>((r) => { timer = setTimeout(r, A.warmMs) as unknown as number; })]); }
278	  catch { /* biên dịch trước lỗi: lần vẽ đầu tự biên dịch như cũ */ }
279	  finally { clearTimeout(timer); }
280	}
