282	/* Nạp mô hình k (nhớ đệm). Không bao giờ ném / từ chối: lỗi → warn một lần, null */
283	export function stRigLoad(model: number): Promise<StRigSource | null> {
284	  let p = cache.get(model);
285	  if (p) return p;
286	  p = (async () => {
287	    try {
288	      const path = A.models[model];
289	      if (!path) throw new Error('không có mô hình số này');
290	      const [{ GLTFLoader }, SU] = await Promise.all([import('three/addons/loaders/GLTFLoader.js'), import('three/addons/utils/SkeletonUtils.js')]);
291	      const gltf = await new GLTFLoader().loadAsync(import.meta.env.BASE_URL + path);
292	      const speeds: Record<string, number> = {};
293	      const json = gltf.parser.json as { animations?: { name?: string; extras?: { speed?: number } }[] };   // AnimationClip không giữ extras: đọc từ JSON gốc
294	      for (const a of json.animations || []) if (a.name) speeds[a.name] = Number(a.extras?.speed) || 0;
295	      const src = stRigSource(gltf.scene, gltf.animations, speeds, Number(gltf.scene.userData?.height) || 0, SU.clone);
296	      await stRigWarm(src.scene);   // nguồn chỉ "sẵn sàng" sau khi shader skinning đã biên dịch: lần hiện đầu không khựng
297	      return src;
298	    } catch (e) {
299	      console.warn(`Đi dạo: không nạp được mô hình người ${model}, dùng hình khối`, e);
300	      return null;
301	    }
302	  })();
303	  cache.set(model, p);
304	  return p;
305	}
