307	/* Một nhân vật đang diễn: bản sao của nguồn + mixer riêng */
308	export class StRig {
309	  readonly root: THREE.Object3D;
310	  readonly src: StRigSource;
311	  readonly mixer: THREE.AnimationMixer;
312	  readonly actions: THREE.AnimationAction[] = [];
313	  readonly w = new Float32Array(NC);    // trọng số đang dùng (đã làm mượt), tổng = 1
314	  rate = 1;                             // hệ số tua đoạn di chuyển đang dùng
315	  phase = 0;                            // pha chung 0–1 của walk / jog / sprint
316	  private readonly mix: StClipMix = { w: new Float32Array(NC), rate: 1, loco: false };
317	  private fresh = true;                 // lần pose đầu: đặt thẳng trọng số đích, không làm mượt
318	  private photo = false;                // khung trước đang ở dáng chụp ảnh
319	
320	  constructor(src: StRigSource) {
321	    this.src = src;
322	    this.root = src.clone(src.scene);
323	    this.root.name = 'stroll-rig';
324	    this.mixer = new THREE.AnimationMixer(this.root);
325	    for (let i = 0; i < NC; i++) {
326	      const a = this.mixer.clipAction(src.clips[i]);
327	      if (i === ST_PHOTO) { a.setLoop(THREE.LoopOnce, 1); a.clampWhenFinished = true; }
328	      if (i >= ST_LOCO0 && i <= ST_LOCO1) a.timeScale = 0;   // thời gian do pha chung đặt
329	      a.enabled = false; a.setEffectiveWeight(0); a.play();
330	      this.actions.push(a);
331	    }
332	  }
333	
334	  /* Mỗi khung: dáng + tốc độ mặt bằng (m/s) + dt (s) → trọng số, pha, mixer.update */
335	  pose(pose: number, speed: number, dt: number): void {
336	    const d = dt > 0 ? (dt < CONFIG.stroll.dtMax ? dt : CONFIG.stroll.dtMax) : 0;   // NaN / âm → 0
337	    const mix = this.mix, w = this.w, acts = this.actions, clips = this.src.clips;
338	    stClipMix(pose, speed, this.src.natural, mix);
339	    const toPhoto = mix.w[ST_PHOTO] === 1;
340	    if (toPhoto && !this.photo) acts[ST_PHOTO].reset();   // chuyển sang chụp ảnh: giơ máy lại từ đầu
341	    this.photo = toPhoto;
342	    const k = this.fresh || !(A.fade > 0) ? 1 : 1 - Math.exp(-d / A.fade);   // fade ≤ 0: chuyển tức thì (tránh 0/0 = NaN khi d = 0)
343	    this.fresh = false;
344	    for (let i = 0; i < NC; i++) w[i] += (mix.w[i] - w[i]) * k;
345	    if (mix.loco) this.rate = mix.rate;   // đang rời nhóm di chuyển: giữ nhịp cũ trong lúc mờ dần
346	    let lw = 0, dur = 0;
347	    for (let i = ST_LOCO0; i <= ST_LOCO1; i++) { lw += w[i]; dur += w[i] * clips[i].duration; }
348	    if (lw > 1e-4 && dur > 1e-6) {
349	      const p = this.phase + d * this.rate / (dur / lw);   // chu kỳ của hỗn hợp = trung bình thời lượng theo trọng số
350	      this.phase = p - Math.floor(p);
351	    }
352	    for (let i = 0; i < NC; i++) {
353	      const a = acts[i], on = w[i] > 1e-4;
354	      if (i >= ST_LOCO0 && i <= ST_LOCO1) a.time = this.phase * clips[i].duration;
355	      if (on !== a.enabled) a.enabled = on;   // đoạn không trọng số: mixer bỏ qua, không tính
356	      a.setEffectiveWeight(on ? w[i] : 0);
357	    }
358	    this.mixer.update(d);
359	  }
360	
361	  /* Đặt lại như vừa tạo: lần pose kế đặt thẳng trọng số đích */
362	  reset(): void { this.fresh = true; this.photo = false; this.phase = 0; this.w.fill(0); }
363	
364	  /* Gỡ khỏi nhóm, bỏ mixer, giải phóng skeleton riêng của bản sao (SkeletonUtils.clone tạo skeleton mới cho mỗi SkinnedMesh; renderer cấp boneTexture cho từng cái).
365	     geometry / texture / vật liệu thuộc nguồn dùng chung nên không dispose */
366	  dispose(): void {
367	    this.mixer.stopAllAction();
368	    this.mixer.uncacheRoot(this.root);
369	    this.root.removeFromParent();
370	    const seen = new Set<THREE.Skeleton>();
371	    this.root.traverse((o) => {
372	      const sk = (o as THREE.SkinnedMesh).isSkinnedMesh ? (o as THREE.SkinnedMesh).skeleton : null;
373	      if (sk && !seen.has(sk)) { seen.add(sk); sk.dispose(); }
374	    });
375	  }
376	}
377	/* ============================ Đi dạo: chọn và trộn đoạn chuyển động của nhân vật có xương (thuần) ============================
378	   Từ dáng (pose) và tốc độ mặt bằng (m/s) tính trọng số năm đoạn idle / walk / jog / sprint / photo và hệ số tua `rate` cho đoạn di chuyển.
379	   Thuần: không import three, không đụng DOM, không cấp phát (gọi mỗi khung cho từng nhân vật, D-018): kết quả ghi vào `out` do bên gọi giữ.
380	   - Di chuyển (pose 1, 2 và 3 khi còn tốc độ ngang): trộn theo tốc độ, walk (≤ walkTo) → jog (jogAt) → sprint (≥ sprintFrom), tuyến tính giữa các mốc; dáng đi / chạy chỉ cho biết đang di chuyển.
381	   - rate = tốc độ thật / tốc độ tự nhiên của đoạn trộn, kẹp [rateMin, rateMax]: chân chạm đất gần đúng không trượt.
382	   - Dáng lạ (khách bản cũ, số ngoài 0..4, NaN) và rơi không còn tốc độ ngang: đứng yên (idle). Khách bản cũ gửi dáng 3 khi nhảy; người đó hiện đứng yên. */
383	import { CONFIG } from '../../config';
384	import { exCharNorm } from '../multi/protocol';
385	import { ST_POSE_WALK, ST_POSE_RUN, ST_POSE_FALL, ST_POSE_PHOTO } from './motion';
386	
387	export const ST_CLIPS = ['idle', 'walk', 'jog', 'sprint', 'photo'] as const;
388	export type StClip = typeof ST_CLIPS[number];
389	
390	export interface StClipMix {
391	  w: Float32Array;   // 5 trọng số theo thứ tự ST_CLIPS, tổng = 1
392	  rate: number;      // hệ số tua đoạn di chuyển
393	  loco: boolean;     // đang di chuyển (walk / jog / sprint có trọng số)
394	}
395	
396	const A = CONFIG.stroll.anim;
397	
398	export function stClipMix(pose: number, speed: number, natural: ArrayLike<number>, out: StClipMix): void {
399	  const w = out.w, v = speed > 0 ? speed : 0;
400	  w[0] = 0; w[1] = 0; w[2] = 0; w[3] = 0; w[4] = 0;
401	  out.rate = 1; out.loco = false;
402	  if (pose === ST_POSE_PHOTO) { w[4] = 1; return; }
403	  const move = pose === ST_POSE_WALK || pose === ST_POSE_RUN || (pose === ST_POSE_FALL && v >= A.fallMin);
404	  if (!move) { w[0] = 1; return; }
405	  out.loco = true;
406	  if (v <= A.walkTo) w[1] = 1;
407	  else if (v < A.jogAt) { const t = (v - A.walkTo) / (A.jogAt - A.walkTo); w[1] = 1 - t; w[2] = t; }
408	  else if (v < A.sprintFrom) { const t = (v - A.jogAt) / (A.sprintFrom - A.jogAt); w[2] = 1 - t; w[3] = t; }
409	  else w[3] = 1;
410	  const nat = w[1] * natural[1] + w[2] * natural[2] + w[3] * natural[3];
411	  const r = nat > 1e-6 ? v / nat : 1;
412	  out.rate = r < A.rateMin ? A.rateMin : r > A.rateMax ? A.rateMax : r;
413	}
414	
415	/* Mô hình của nhân vật người chơi chọn (0 nam, 1 nữ; giá trị lạ / không có = nam). Mình và người khác dùng chung hàm này:
416	   mô hình chỉ phụ thuộc lựa chọn của chủ nhân vật, không theo slot hay theo máy đang nhìn, nên mọi máy thấy cùng một người như nhau */
417	export function stCharModel(ch: unknown): number { return A.chars[exCharNorm(ch)]; }
418	/* ===== Đi dạo: nhân vật người chơi chọn ở sảnh (0 nam, 1 nữ) =====
419	   Lựa chọn nhớ ở localStorage (như tên, multi/lobby.ts) nên giữ qua xuất phát lại, kết nối lại và tải lại trang; bộ nhớ bị chặn thì chỉ giữ trong phiên trang.
420	   Giá trị lạ / chưa chọn: nam (exCharNorm). Mô hình ứng với nhân vật: stCharModel (anim.ts). Lựa chọn tới máy khác qua tin join (multi/session.ts) và walkers của lobby. */
421	import { exCharNorm } from '../multi/protocol';
422	
423	const KEY = 'stChar';
424	let cur = -1;   // -1: chưa đọc bộ nhớ
425	
426	export const stChar = {
427	  get(): number {
428	    if (cur < 0) { try { cur = exCharNorm(Number(localStorage.getItem(KEY))); } catch { cur = 0; } }
429	    return cur;
430	  },
431	  set(ch: number): void {
432	    cur = exCharNorm(ch);
433	    try { localStorage.setItem(KEY, String(cur)); } catch { /* bộ nhớ trình duyệt bị chặn (hoặc không có, trong test đơn vị) */ }
434	  }
435	};
436	/* ============================ Lái xe máy: người lái có xương (src/explore/bike/rider.ts) ============================
437	   Spec D-040 §6, §17.10 (tư thế ngồi = bảng góc khớp trong code + IK, không chạy lại gen:people).
438	   - Nhân vật: nguồn của Đi dạo (stroll/rig.ts stRigLoad, p0 nam / p3 nữ theo stCharModel), một bản sao (src.clone = SkeletonUtils.clone), KHÔNG AnimationMixer:
439	     mỗi khung xương về tư thế đứng chữ A của mô hình (PlBones.restore) rồi cộng góc. Hệ C = hệ gốc bản sao: +X trước mặt, +Y lên, +Z bên phải (trùng hệ thân xe).
440	   - Cây nút: neo `seat` của xe (đọc lại bike.anchors mỗi khung: neo đổi khi hình tạm đổi sang mô hình thật) → group 'bike-rider' → bản sao nhân vật
441	     (dời để xương Pelvis ở rider.seat so với đỉnh yên). Nhờ vậy người theo đủ yaw / pitch / nghiêng / giảm xóc của phần trên lò xo.
442	   - Mỗi khung: 1) bảng góc khớp (bkRiderPose): lưng cúi chia ba đốt, cổ, đầu, gập hông, gập gối, đùi xoay ra, xương đòn; cộng lò xo phản ứng:
443	     lưng ngả theo gia tốc dọc, đầu bù (1 − headLean) độ nghiêng, đầu quay theo góc lái; 2) IK chân: plTwoBone hông → gối → cổ chân tới neo foot_l / foot_r
444	     (+ rider.ankle), đùi và cẳng chân xoay cung ngắn nhất từ tư thế bảng (giữ độ xoắn của bảng), bàn chân về hướng lúc đứng (phẳng trên sàn);
445	     3) IK tay: PlBones.ik của người treo dù với bộ số rider.arm / rider.finger, điểm nắm tới neo grip_l / grip_r (con của cổ lái: bẻ lái thì tay theo).
446	   - Mũ bảo hiểm nửa đầu: nửa khối cầu (SphereGeometry cắt nửa) gắn xương đầu, vật liệu MeshStandardMaterial màu theo đỉnh = cùng chương trình với hình tạm
447	     của xe (model.ts bkTempMaterial, đã làm nóng) nên không thêm program. Lớp 1, không bóng như xe.
448	   - Lệnh vẽ: nhân vật Rocketbox là 1 SkinnedMesh 3 primitive (thân, đầu, mảnh alpha) = 3 lệnh, như nhân vật đi dạo; mũ 1 lệnh.
449	   - Góc nhìn thứ nhất: xương đầu thu về scale ≈ 0 (mũ là con của xương đầu nên ẩn theo); thân, tay giữ.
450	   - Chưa có mô hình xe thật (bike.real = false): người ẩn, không tính IK (hình tạm của xe đã có người khối; hai người chồng nhau thì sai).
451	   Không cấp phát mỗi khung (D-018). */
452	import * as THREE from 'three';
453	import { CONFIG } from '../../config';
454	import { plTwoBone } from '../pilot/ik';
455	import { PlBones } from '../pilot/bones';
456	import { stRigLoad, type StRigSource } from '../stroll/rig';
457	import { stCharModel } from '../stroll/anim';
458	import type { BkBike } from './model';
459	
460	export interface BkRiderSig { lean: number; acc: number; susF: number; susR: number; steer: number }   // lean rad (trái +), acc m/s² gia tốc dọc, susF / susR m lún giảm xóc, steer rad (trái +)
461	
462	const RC = CONFIG.bike.rider;
463	const TAU = Math.PI * 2;
464	const A_REF = (50 / 3.6) / CONFIG.bike.perf.t50;   // m/s² — gia tốc khi vặn hết ga dưới 50 km/h (motion.ts A0)
465	
466	/* ===== Bảng góc khớp tư thế ngồi nền (rad), thứ tự cố định ===== */
467	export const BK_POSE = { spine: 0, neck: 1, head: 2, hip: 3, knee: 4, legSplit: 5, ankle: 6, clavicle: 7, clavicleFore: 8 } as const;
468	export const BK_POSE_N = 9;
469	export function bkRiderPose(out: Float32Array): void {
470	  const P = RC.pose;
471	  out[BK_POSE.spine] = P.spine; out[BK_POSE.neck] = P.neck; out[BK_POSE.head] = P.head;
472	  out[BK_POSE.hip] = P.hip; out[BK_POSE.knee] = P.knee; out[BK_POSE.legSplit] = P.legSplit; out[BK_POSE.ankle] = P.ankle;
473	  out[BK_POSE.clavicle] = P.clavicle; out[BK_POSE.clavicleFore] = P.clavicleFore;
474	}
475	
476	/* Nạp nhân vật ch (0 nam / 1 nữ) — chung bộ nạp, bộ đệm và làm nóng với Đi dạo. Không bao giờ từ chối: lỗi → null */
477	export function bkRiderLoad(ch: number): Promise<StRigSource | null> { return stRigLoad(stCharModel(ch)); }
478	
479	const AZ = new THREE.Vector3(0, 0, 1);
480	const _inv = new THREE.Matrix4(), _q = new THREE.Quaternion(), _q2 = new THREE.Quaternion(), _qa = new THREE.Quaternion(), _qb = new THREE.Quaternion(), _qc = new THREE.Quaternion();
481	const _h = new THREE.Vector3(), _k = new THREE.Vector3(), _a = new THREE.Vector3(), _d = new THREE.Vector3(), _d2 = new THREE.Vector3();
482	const _hip = [0, 0, 0], _tgt = [0, 0, 0], _pole = [0, 0, 0], _knee = [0, 0, 0], _end = [0, 0, 0];
483	const _tL = new THREE.Vector3(), _tR = new THREE.Vector3();
484	
485	/* Hình học mũ: nửa khối cầu (vỏ trên), màu theo đỉnh */
486	function bkHelmetGeometry(): THREE.BufferGeometry {
487	  const H = RC.helmet, g = new THREE.SphereGeometry(H.r, 20, 8, 0, TAU, 0, Math.PI / 2);
488	  const c = new THREE.Color(H.color), n = g.getAttribute('position').count, col = new Float32Array(n * 3);
489	  for (let i = 0; i < n; i++) { col[i * 3] = c.r; col[i * 3 + 1] = c.g; col[i * 3 + 2] = c.b; }
490	  g.setAttribute('color', new THREE.BufferAttribute(col, 3));
491	  return g;
492	}
493	
494	export class BkRider {
495	  readonly group = new THREE.Group();
496	  readonly root: THREE.Object3D;
497	  readonly bones: PlBones;
498	  readonly helmet: THREE.Mesh;
499	  private readonly pose = new Float32Array(BK_POSE_N);
500	  private readonly feet: THREE.Object3D[];
501	  private readonly legL1 = [0, 0]; private readonly legL2 = [0, 0];   // m — đùi, cẳng chân
502	  private readonly footRest = [new THREE.Quaternion(), new THREE.Quaternion()];   // hướng bàn chân trong hệ C lúc đứng (phẳng)
503	  private readonly footT = [new THREE.Vector3(), new THREE.Vector3()];   // đích cổ chân, hệ C (cho debug)
504	  private readonly sx = new Float64Array(3); private readonly sv = new Float64Array(3);   // lò xo: lưng chúi, đầu bù nghiêng, đầu quay
505	  private disposed = false;
506	
507	  constructor(src: StRigSource) {
508	    this.group.name = 'bike-rider';
509	    this.root = src.clone(src.scene);
510	    this.root.name = 'bike-rider-body';
511	    this.group.add(this.root);
512	    const b = this.bones = new PlBones(this.root);   // thiếu xương thì ném (index.ts bắt)
513	    if (!b.foot[0] || !b.foot[1]) throw new Error('thiếu xương bàn chân');
514	    this.feet = [b.foot[0], b.foot[1]];
515	    /* số đo ở tư thế đứng: tay (PlBones.measure với bộ số của xe máy), chân, hướng bàn chân, chỗ xương hông */
516	    b.measure(RC.arm);
517	    b.updateMatrices();
518	    for (let i = 0; i < 2; i++) {
519	      b.pC(b.thigh[i], _h); b.pC(b.calf[i], _k); b.pC(this.feet[i], _a);
520	      this.legL1[i] = Math.max(0.05, _h.distanceTo(_k)); this.legL2[i] = Math.max(0.05, _k.distanceTo(_a));
521	      b.qC(this.feet[i], this.footRest[i]);
522	    }
523	    b.pC(b.pelvis, _h);
524	    this.root.position.set(RC.seat.fore - _h.x, RC.seat.up - _h.y, -_h.z);
525	    /* mũ: trục theo hệ C lúc đứng thẳng, tâm trên xương đầu; con của xương đầu */
526	    const H = RC.helmet;
527	    this.helmet = new THREE.Mesh(bkHelmetGeometry(), new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.45, metalness: 0.1 }));
528	    this.helmet.name = 'bike-helmet';
529	    b.qC(b.head, _q).invert();
530	    const hs = _h.setFromMatrixScale(_inv.copy(this.root.matrixWorld).invert().multiply(b.head.matrixWorld)).x || 1;   // tỉ lệ xương đầu so với hệ C (Rocketbox: Bip01 scale 0,01, đơn vị cm)
531	    this.helmet.quaternion.copy(_q).multiply(_qa.setFromAxisAngle(AZ, H.pitch));   // trục mũ = hệ C ngửa pitch quanh trục ngang
532	    this.helmet.position.set(H.fore, H.up, 0).applyQuaternion(_q).divideScalar(hs);
533	    this.helmet.scale.set(H.scale[0] / hs, H.scale[1] / hs, H.scale[2] / hs);
534	    b.head.add(this.helmet);
535	    this.group.traverse((o) => {
536	      o.layers.set(1);
537	      const m = o as THREE.Mesh;
538	      if (m.isMesh) { m.castShadow = false; m.receiveShadow = false; m.frustumCulled = false; }
539	    });
540	    bkRiderPose(this.pose);
541	    this.group.visible = false;
542	  }
543	
544	  /* Lò xo bậc hai ba kênh tới đích, bước con ≤ 1/120 s (ổn định với mọi dt đã kẹp) */
545	  private spring(sig: BkRiderSig, d: number): void {
546	    const acc = Number.isFinite(sig.acc) ? sig.acc : 0, lean = Number.isFinite(sig.lean) ? sig.lean : 0, steer = Number.isFinite(sig.steer) ? sig.steer : 0;
547	    const t0 = acc >= 0 ? -RC.accLean * Math.min(1, acc / A_REF) : RC.brakeLean * Math.min(1, -acc / CONFIG.bike.perf.hardBrake);
548	    const t1 = lean * (1 - RC.headLean), t2 = steer * RC.steerLook;
549	    if (!(d > 0)) return;
550	    const w = TAU * RC.hz, z = RC.damp, n = Math.ceil(d * 120), h = d / n, x = this.sx, v = this.sv;
551	    for (let s = 0; s < n; s++) {
552	      v[0] += (w * w * (t0 - x[0]) - 2 * z * w * v[0]) * h; x[0] += v[0] * h;
553	      v[1] += (w * w * (t1 - x[1]) - 2 * z * w * v[1]) * h; x[1] += v[1] * h;
554	      v[2] += (w * w * (t2 - x[2]) - 2 * z * w * v[2]) * h; x[2] += v[2] * h;
555	    }
556	  }
557	
558	  /* Xoay xương o thêm R (hệ C) quanh khớp của nó (như PlBones.rotC) */
559	  private rotC(o: THREE.Object3D, R: THREE.Quaternion): void {
560	    this.bones.qC(o.parent, _q2);
561	    o.quaternion.premultiply(_q.copy(_q2).invert().multiply(R).multiply(_q2));
562	  }
563	
564	  /* Vị trí neo trong hệ C (ma trận thế giới đã cập nhật; _inv = nghịch đảo ma trận gốc bản sao) */
565	  private toC(o: THREE.Object3D, out: THREE.Vector3): THREE.Vector3 { return out.setFromMatrixPosition(o.matrixWorld).applyMatrix4(_inv); }
566	
567	  update(bike: BkBike, sig: BkRiderSig, dt: number): void {
568	    if (this.disposed) return;
569	    if (!bike.real) { this.group.visible = false; return; }
570	    const an = bike.anchors, b = this.bones, P = this.pose, B = BK_POSE;
571	    if (this.group.parent !== an.seat) an.seat.add(this.group);
572	    this.group.visible = true;
573	    const d = dt > 0 && Number.isFinite(dt) ? Math.min(dt, RC.dtMax) : 0;
574	    this.spring(sig, d);
575	    const x = this.sx;
576	    /* 1) bảng góc khớp + phản ứng (rotE: Euler YZX trong hệ C; quay âm quanh +Z = cúi trước; quay dương quanh +X = nghiêng phải; quay dương quanh +Y = quay trái) */
577	    b.restore();
578	    const k = 1 / b.spines.length;
579	    for (const s of b.spines) b.rotE(s, 0, 0, -(P[B.spine] + x[0]) * k);
580	    b.rotE(b.neck, 0, 0, -P[B.neck]);
581	    b.rotE(b.head, x[1], x[2], -P[B.head]);
582	    for (let i = 0; i < 2; i++) {
583	      const side = i ? 1 : -1;
584	      b.rotE(b.thigh[i], 0, -side * P[B.legSplit], P[B.hip]);
585	      b.rotE(b.calf[i], 0, 0, -P[B.knee]);
586	    }
587	    for (const a of b.arms) b.rotE(a.clav, -a.side * P[B.clavicle], 0, P[B.clavicleFore]);
588	    /* 2) chân */
589	    bike.group.updateMatrixWorld(true);
590	    b.updateMatrices();
591	    _inv.copy(this.root.matrixWorld).invert();
592	    const LP = RC.legPole, AK = RC.ankle;
593	    for (let i = 0; i < 2; i++) {
594	      const side = i ? 1 : -1, th = b.thigh[i], ca = b.calf[i], ft = this.feet[i], T = this.footT[i];
595	      this.toC(i ? an.footR : an.footL, T);
596	      T.x -= AK.back; T.y += AK.up;
597	      b.pC(th, _h); b.pC(ca, _k); b.pC(ft, _a);
598	      _hip[0] = _h.x; _hip[1] = _h.y; _hip[2] = _h.z;
599	      _tgt[0] = T.x; _tgt[1] = T.y; _tgt[2] = T.z;
600	      _pole[0] = _h.x + LP[0]; _pole[1] = _h.y + LP[1]; _pole[2] = _h.z + side * LP[2];
601	      plTwoBone(_hip, this.legL1[i], this.legL2[i], _tgt, _pole, _knee, _end);
602	      /* đùi: cung ngắn nhất từ hướng hiện tại (bảng) tới hướng hông → gối mới */
603	      _d.copy(_k).sub(_h).normalize(); _d2.set(_knee[0] - _h.x, _knee[1] - _h.y, _knee[2] - _h.z).normalize();
604	      _qa.setFromUnitVectors(_d, _d2);
605	      this.rotC(th, _qa);
606	      /* cẳng chân: hướng cũ (đã quay theo đùi) → gối → cổ chân mới */
607	      _d.copy(_a).sub(_k).normalize().applyQuaternion(_qa);
608	      _d2.set(_end[0] - _knee[0], _end[1] - _knee[1], _end[2] - _knee[2]).normalize();
609	      _qb.setFromUnitVectors(_d, _d2);
610	      this.rotC(ca, _qb);
611	      /* bàn chân: hướng lúc đứng (phẳng) + góc bảng quanh trục ngang */
612	      b.qC(ca, _q2).invert();
613	      ft.quaternion.copy(_q2).multiply(_qc.setFromAxisAngle(AZ, -P[B.ankle]).multiply(this.footRest[i]));
614	    }
615	    /* 3) tay */
616	    b.updateMatrices();
617	    this.toC(an.gripL, _tL); this.toC(an.gripR, _tR);
618	    b.ik(b.arms[0], _tL, RC.arm, RC.finger);
619	    b.ik(b.arms[1], _tR, RC.arm, RC.finger);
620	  }
621	
622	  /* Góc nhìn thứ nhất: thu xương đầu (và mũ) về ≈ 0 */
623	  setFirstPerson(on: boolean): void {
624	    this.bones.head.scale.setScalar(on ? 1e-4 : 1);
625	  }
626	
627	  /* Mắt trong hệ của nút frame (camera góc thứ nhất đo một lần ở tư thế ngồi nền: index.ts riderEye): điểm giữa hai xương mắt Bip01_LEye / REye
628	     (Rocketbox có), trả true; thiếu thì vị trí xương đầu, trả false (người gọi cộng cam1.headEye) */
629	  eyeLocal(frame: THREE.Object3D, out: THREE.Vector3): boolean {
630	    frame.updateWorldMatrix(true, true);
631	    const l = this.root.getObjectByName('Bip01_LEye') ?? this.root.getObjectByName('Bip01 LEye'), r = this.root.getObjectByName('Bip01_REye') ?? this.root.getObjectByName('Bip01 REye');
632	    if (l && r) out.setFromMatrixPosition(l.matrixWorld).add(_a.setFromMatrixPosition(r.matrixWorld)).multiplyScalar(0.5);
633	    else out.setFromMatrixPosition(this.bones.head.matrixWorld);
634	    frame.worldToLocal(out);
635	    return !!(l && r);
636	  }
637	
638	  /* m — khoảng cách điểm nắm – tay nắm (hai tay), cổ chân – đích cổ chân trên sàn (hai chân), sau update gần nhất */
639	  debug(): { handL: number; handR: number; footL: number; footR: number } {
640	    const b = this.bones;
641	    b.updateMatrices();
642	    _inv.copy(this.root.matrixWorld).invert();
643	    const f = (i: number): number => b.pC(this.feet[i], new THREE.Vector3()).distanceTo(this.footT[i]);
644	    return { handL: b.handErr(0), handR: b.handErr(1), footL: f(0), footR: f(1) };
645	  }
646	
647	  /* Gỡ khỏi xe, giải phóng skeleton riêng của bản sao, hình học / vật liệu mũ. Hình học / texture / vật liệu nhân vật thuộc nguồn dùng chung nên giữ */
648	  dispose(): void {
649	    if (this.disposed) return;
650	    this.disposed = true;
651	    this.group.removeFromParent();
652	    const seen = new Set<THREE.Skeleton>();
653	    this.root.traverse((o) => {
654	      const sk = (o as THREE.SkinnedMesh).isSkinnedMesh ? (o as THREE.SkinnedMesh).skeleton : null;
655	      if (sk && !seen.has(sk)) { seen.add(sk); sk.dispose(); }
656	    });
657	    this.helmet.geometry.dispose();
658	    (this.helmet.material as THREE.Material).dispose();
659	  }
660	}
661

