/* ===== Đi dạo: nhân vật hiển thị (mình + tối đa 4 người khác) =====
   Nhóm 'stroll-people' (THREE.Group): mỗi slot đi dạo (đi một mình dùng 0) hiện bằng một nhân vật có xương (rig.ts). Mô hình theo nhân vật chủ slot chọn (stCharModel, anim.ts): mình theo stChar (char.ts), người khác theo ch trong walkers của lobby;
   ch tới cùng lúc với tên (sync) và trước mẫu vị trí đầu, nên không có lúc nào người khác được dựng bằng nhân vật mặc định rồi mới đổi.
   Mô hình chưa nạp xong hoặc nạp lỗi: slot hiện bằng hình khối (blocky.ts, InstancedMesh con của nhóm) nên lỗi mạng không bao giờ làm mất nhân vật.
   - Nạp lười: lần đầu một slot đang hiện cần mô hình k thì gọi bộ nạp (stRigLoad, test thay bằng __setLoader); kết quả chỉ vào bộ đệm sources[k].
     Bản sao chỉ tạo trong vòng khung (stPlace) cho slot đang hiện và đúng mô hình lúc đó, nên kết quả về muộn (slot đã đổi chủ, đã trống, đã rời chế độ) không bao giờ gắn nhầm (Review Focus 2).
   - Slot đổi chủ / đổi mô hình / clear(): gỡ bản sao khỏi nhóm, bỏ mixer (StRig.dispose; geometry / texture của nguồn dùng chung giữ lại).
   - dt cho mixer: mình nhận dt của bước chuyển động qua setSelf; người khác dùng hiệu nowMs giữa hai lần update; StRig kẹp ≤ stroll.dtMax (Review Focus 3).
   - Người khác nội suy bằng ExTrack như remote.ts (trường thứ 6 chở pose, lấy mẫu bậc thang step = true); slot đổi chủ thì xóa mẫu và ẩn tới mẫu đầu.
   Lớp 1, không đổ bóng (rig.ts, blocky.ts). build() chỉ dựng (lần đầu gọi, không lúc dựng cảnh), bên gọi tự thêm vào scene. Không cấp phát mỗi khung (D-018). */
import * as THREE from 'three';
import { CONFIG } from '../../config';
import { ExTrack, type ExPose } from '../multi/interp';
import { exCharNorm, type Flyer } from '../multi/protocol';
import { ST_POSE_WALK, ST_POSE_RUN, type StState } from './motion';
import { stCharModel } from './anim';
import { stChar } from './char';
import { stBlocky } from './blocky';
import { stRigLoad, StRig, type StRigSource } from './rig';

export { stAvatarVar } from './blocky';

const M = CONFIG.explore.multi, C = CONFIG.stroll, N = M.stroll.slots;

interface StSlot {
  who: 0 | 1 | 2;             // 0 trống, 1 mình, 2 người khác
  name: string | null;        // tên người khác (từ sync); null = không có
  ch: number;                 // nhân vật người khác chọn (từ sync; máy chủ cũ không gửi = 0 nam). Slot của mình không đọc trường này
  track: ExTrack;
  pose: ExPose;               // đệm lấy mẫu (bank chở pose)
  st: { x: number; y: number; z: number; yaw: number; pose: number };   // trạng thái trả cho slotState
  live: boolean;              // đang hiện
  rig: StRig | null;          // nhân vật có xương đang gắn (null: hình khối)
  model: number;              // mô hình của rig
}

const slots: StSlot[] = Array.from({ length: N }, () => ({
  who: 0 as const, name: null, ch: 0, track: new ExTrack(), pose: { x: 0, y: 0, z: 0, yaw: 0, bank: 0 },
  st: { x: 0, y: 0, z: 0, yaw: 0, pose: 0 }, live: false, rig: null, model: -1
}));
let group: THREE.Group | null = null, me = -1, lastNow = -1;

/* Bộ đệm mô hình: undefined = chưa có kết quả, null = nạp lỗi (giữ hình khối, không thử lại), còn lại = nguồn */
let loader: (model: number) => Promise<StRigSource | null> = stRigLoad;
let sources: (StRigSource | null | undefined)[] = [];
let asked = new Set<number>();
let gen = 0;   // thế hệ bộ nạp: __setLoader tăng để kết quả của bộ nạp cũ bị bỏ

/* Nguồn của mô hình k nếu đã nạp xong; chưa thì bắt đầu nạp (một lần) và trả null. Không ném */
function stNeed(model: number): StRigSource | null {
  const s = sources[model];
  if (s !== undefined) return s;
  if (!asked.has(model)) {
    asked.add(model);
    const g = gen;
    const done = (r: StRigSource | null) => { if (g === gen) sources[model] = r; };
    try { loader(model).then(done, () => done(null)); } catch { done(null); }
  }
  return null;
}

/* Mô hình của slot: mình theo lựa chọn của mình, người khác theo lựa chọn của họ (không bao giờ lấy lựa chọn của mình cho người khác) */
const stModelOf = (s: StSlot): number => stCharModel(s.who === 1 ? stChar.get() : s.ch);

/* Gỡ nhân vật thật của slot i (đổi chủ, đổi mô hình, rời chế độ) */
function stDrop(i: number): void {
  const s = slots[i];
  if (!s.rig) return;
  s.rig.dispose(); s.rig = null; s.model = -1;
}

/* Đặt slot i theo s.st: nhân vật thật nếu mô hình đã có, không thì hình khối. speed (m/s) chọn đoạn / nhịp bước, dt (s) cho mixer */
function stPlace(i: number, speed: number, dt: number): void {
  const s = slots[i];
  if (!group) return;
  if (!s.live) { stBlocky.place(i, null, 0); if (s.rig) s.rig.root.visible = false; return; }
  const model = stModelOf(s);
  if (s.rig && s.model !== model) stDrop(i);
  if (!s.rig) {
    const src = stNeed(model);
    if (src) { s.rig = new StRig(src); s.model = model; group.add(s.rig.root); }
  }
  const t = s.st;
  if (!s.rig) { stBlocky.place(i, t, speed); return; }
  stBlocky.place(i, null, 0);
  const r = s.rig.root;
  r.visible = true;
  r.position.set(t.x, t.y, t.z); r.rotation.set(0, t.yaw, 0);   // mô hình hướng +X như hình khối: yaw quanh Y
  s.rig.pose(t.pose, speed, dt);
}

function stHide(i: number): void {
  const s = slots[i];
  s.track.reset(); s.live = false;
  stDrop(i);
  stPlace(i, 0, 0);
}

function stRefreshVisible(): void {
  if (!group) return;
  let any = false;
  for (const s of slots) if (s.live) { any = true; break; }
  group.visible = any;
  stBlocky.refresh();
}

/* Tốc độ danh định theo dáng cho người khác (gói vị trí không có tốc độ) */
const stPoseSpeed = (pose: number) => (pose === ST_POSE_RUN ? C.run : pose === ST_POSE_WALK ? C.walk : 0);

export const stAvatars = {
  get mesh(): THREE.Group | null { return group; },
  get self(): number { return me; },   // slot nhân vật của mình, -1 nếu không có (nhãn tên bỏ qua slot này)

  /* Dựng lần đầu gọi (lười, ngoài thứ tự dựng cảnh), các lần sau trả lại nhóm cũ. Bên gọi thêm vào scene */
  build(): THREE.Group {
    if (group) return group;
    group = new THREE.Group();
    group.name = 'stroll-people';
    group.add(stBlocky.build());
    group.visible = false;
    return group;
  },

  /* Bắt đầu nạp mô hình nhân vật mình đang chọn trước khi cần (lúc chọn thẻ Đi dạo, lúc đổi nhân vật ở sảnh). Không ném */
  preload(): void { stNeed(stCharModel(stChar.get())); },

  /* Nhân vật của mình ở slot (đi một mình: 0); s = null thì bỏ hiện slot đó. dt (s): bước chuyển động vừa chạy, cho mixer */
  setSelf(slot: number, s: StState | null, dt = 0): void {
    if (s === null) {
      if (me >= 0 && slots[me]?.who === 1) { slots[me].who = 0; stHide(me); }
      me = -1; stRefreshVisible(); return;
    }
    const x = slots[slot];
    if (!x) return;
    if (me !== slot && me >= 0 && slots[me]?.who === 1) { slots[me].who = 0; stHide(me); }
    if (x.who !== 1) stDrop(slot);   // slot vừa thành của mình: bản sao người khác (nếu còn) bỏ
    me = slot; x.who = 1; x.track.reset();
    const t = x.st;
    t.x = s.x; t.y = s.y; t.z = s.z; t.yaw = s.yaw; t.pose = s.pose;
    x.live = true;
    stPlace(slot, s.speed, dt);
    stRefreshVisible();
  },

  /* Danh sách người đi dạo đổi (sảnh, vào, ra): slot đổi chủ thì xóa mẫu, ẩn tới mẫu đầu; slot trống thì ẩn. Slot của mình do setSelf lo */
  sync(walkers: Flyer[], mySlot: number): void {
    /* Được cấp slot khác: bỏ nhân vật ở slot cũ, setSelf sẽ đặt lại. mySlot < 0 (mất kết nối → đi một mình, bị thu chỗ → xem) thì giữ nguyên:
       đi tiếp một mình vẫn setSelf cùng slot (không gỡ rồi dựng lại bản sao, chuyển động không phát lại từ đầu); sang xem thì stroll gọi setSelf(null) */
    if (mySlot >= 0 && mySlot !== me && me >= 0 && slots[me]?.who === 1) { slots[me].who = 0; stHide(me); me = -1; }
    for (let i = 0; i < N; i++) {
      const s = slots[i];
      let name: string | null = null, ch = 0;
      for (const w of walkers) if (w.slot === i) { name = w.name; ch = exCharNorm(w.ch); break; }
      if (i === me) { s.name = name; continue; }   // nhân vật của mình: chỉ setSelf đổi
      if (i === mySlot) { s.name = name; if (s.who === 2) { s.who = 0; stHide(i); } continue; }   // slot vừa thành của mình: bỏ người khác cũ, chờ setSelf
      if (name === null) { s.name = null; if (s.who === 2) { s.who = 0; stHide(i); } continue; }
      if (name !== s.name || ch !== s.ch || s.who !== 2) { s.name = name; s.ch = ch; s.who = 2; stHide(i); }   // đổi chủ (tên hoặc nhân vật khác): gỡ bản sao cũ
    }
    stRefreshVisible();
  },

  /* Gói vị trí gộp: w = [slot, x, y, z, yaw, pose, giờ gửi?]; chỉ nhận slot người khác đã biết chủ */
  onPos(w: number[][], nowMs: number): void {
    for (const e of w) {
      const i = e[0], s = slots[i];
      if (!s || i === me || s.who !== 2) continue;
      s.track.feed(e, nowMs, M);
    }
  },

  /* Mỗi khung: đặt người khác theo mẫu nội suy (pose bậc thang); dt mixer = hiệu nowMs giữa hai lần gọi (StRig kẹp dtMax) */
  update(nowMs: number): void {
    const dt = lastNow < 0 ? 0 : (nowMs - lastNow) / 1000;
    lastNow = nowMs;
    const t = nowMs - M.interpSends * 1000 / M.sendHz;
    for (let i = 0; i < N; i++) {
      const s = slots[i];
      if (s.who !== 2) continue;
      if (!s.track.sample(t, s.pose, true)) { if (s.live) { s.live = false; stPlace(i, 0, 0); } continue; }
      const p = s.pose, st = s.st;
      st.x = p.x; st.y = p.y; st.z = p.z; st.yaw = p.yaw; st.pose = Math.round(p.bank);
      s.live = true;
      stPlace(i, stPoseSpeed(st.pose), dt);
    }
    stRefreshVisible();
  },

  /* Trạng thái đang hiện của slot (cho nhãn tên, camera dù lượn); null nếu trống hoặc chưa có mẫu */
  slotState(slot: number): { x: number; y: number; z: number; yaw: number; pose: number } | null {
    const s = slots[slot];
    return s && s.live ? s.st : null;
  },

  /* Tên người ở slot (theo sync, cả slot của mình); null nếu trống hoặc đi một mình */
  name(slot: number): string | null { const s = slots[slot]; return s ? s.name : null; },

  /* Rời chế độ / rời phòng: gỡ hết nhân vật thật, ẩn hình khối, quên tên (nhóm và bộ đệm mô hình giữ lại để tái dùng) */
  clear(): void {
    me = -1; lastNow = -1;
    for (let i = 0; i < N; i++) { const s = slots[i]; s.who = 0; s.name = null; s.ch = 0; stHide(i); }
    stRefreshVisible();
  },

  /* Cho test (stroll-check, multi-check): slot trống → null; real = đang hiện bằng nhân vật có xương; mix = trọng số ST_CLIPS đang dùng */
  debug(slot: number): { model: number; real: boolean; mix: number[]; rate: number } | null {
    const s = slots[slot];
    if (!s || s.who === 0) return null;
    const r = s.rig, real = !!r && s.live && r.root.visible;
    return { model: r ? s.model : stModelOf(s), real, mix: r ? Array.from(r.w) : [], rate: r ? r.rate : 0 };
  },

  /* Chỉ dùng trong unit test: thay bộ nạp (null = stRigLoad thật) và quên bộ đệm mô hình */
  __setLoader(fn: ((model: number) => Promise<StRigSource | null>) | null): void {
    loader = fn || stRigLoad; gen++;
    sources = []; asked = new Set();
  }
};
/* ===== Đi dạo: nạp mô hình người có xương (public/people/p<k>.glb) và một nhân vật đang diễn =====
   - stRigLoad(k): import() động GLTFLoader + SkeletonUtils (chunk riêng, trang thường không tải), nạp p<k>.glb một lần, nhớ đệm theo k.
     Lỗi bất kỳ (mạng, file hỏng, thiếu đoạn) → console.warn một lần cho mô hình đó, trả null, không thử lại trong phiên; promise không bao giờ bị từ chối.
   - stRigSource: chuẩn hóa cảnh đã nạp: lớp 1 (không vào phản chiếu nước), không đổ / nhận bóng, tắt frustumCulled (hộp bao theo tư thế gốc sai khi diễn),
     vật liệu metalness 0, roughness 0.85; mảnh alpha (alphaMode MASK) giữ alphaTest, không trộn trong suốt. Tốc độ tự nhiên từng đoạn đọc từ extras.speed.
   - Làm nóng: sau khi nạp, stRigLoad chờ hàm do stRigSetWarm gắn (compileAsync theo cảnh chính, ≤ anim.warmMs) rồi mới trả nguồn (D-018).
   - StRig: một bản sao (SkeletonUtils.clone, dùng chung geometry / texture / vật liệu với nguồn) + AnimationMixer riêng.
     pose(): trọng số đích từ stClipMix (anim.ts), làm mượt về đích với hằng thời gian anim.fade; walk / jog / sprint đồng pha bằng một pha chung 0–1
     (đặt action.time = pha × thời lượng đoạn, timeScale 0 để mixer không tự tua); photo LoopOnce + clampWhenFinished, phát lại từ đầu mỗi lần chuyển sang dáng chụp ảnh.
     dt kẹp [0, stroll.dtMax] (tab ẩn rồi quay lại không làm nhảy pha). Không cấp phát mỗi khung (D-018).
   - Mô hình: mét, chân ở y = 0, mặt hướng +X (như hình khối), xương Rocketbox (Bip01_*). docs/superpowers/specs/2026-11-12-nguoi-di-dao-that-design.md §5, §7 */
import * as THREE from 'three';
import { CONFIG } from '../../config';
import { ST_CLIPS, stClipMix, type StClipMix } from './anim';

const A = CONFIG.stroll.anim, NC = ST_CLIPS.length;
const ST_LOCO0 = 1, ST_LOCO1 = 3, ST_PHOTO = 4;   // chỉ số trong ST_CLIPS: walk..sprint, photo (idle = 0)

export interface StRigSource {
  scene: THREE.Object3D;                                   // cảnh gốc (không thêm vào scene; chỉ để sao chép)
  clips: THREE.AnimationClip[];                            // 5 đoạn theo thứ tự ST_CLIPS
  natural: Float32Array;                                   // tốc độ tự nhiên từng đoạn theo ST_CLIPS, m/s (idle / photo = 0)
  height: number;                                          // chiều cao tư thế đứng, m (0 nếu file không ghi)
  clone: (o: THREE.Object3D) => THREE.Object3D;            // SkeletonUtils.clone (test truyền bản giả)
}

/* Chuẩn hóa cảnh + đoạn đã nạp thành nguồn dùng chung. speeds: tên đoạn → m/s. Thiếu đoạn nào thì ném lỗi (stRigLoad bắt, trả null) */
export function stRigSource(scene: THREE.Object3D, clips: THREE.AnimationClip[], speeds: Record<string, number>, height: number, clone: (o: THREE.Object3D) => THREE.Object3D): StRigSource {
  const out: THREE.AnimationClip[] = [], natural = new Float32Array(NC);
  for (let i = 0; i < NC; i++) {
    const c = clips.find(x => x.name === ST_CLIPS[i]);
    if (!c) throw new Error(`thiếu đoạn ${ST_CLIPS[i]}`);
    out.push(c);
    natural[i] = Math.max(0, Number(speeds[ST_CLIPS[i]]) || 0);
  }
  scene.traverse((o) => {
    o.layers.set(1);
    const m = o as THREE.Mesh;
    if (!m.isMesh) return;
    m.castShadow = false; m.receiveShadow = false; m.frustumCulled = false;
    const mats = Array.isArray(m.material) ? m.material : [m.material];
    for (const mat of mats) {
      const s = mat as THREE.MeshStandardMaterial;
      if (s.isMeshStandardMaterial) { s.metalness = 0; s.roughness = 0.85; }
      if (s.alphaTest > 0) s.transparent = false;   // MASK: cắt theo alphaTest, không trộn trong suốt (không cần sắp thứ tự)
    }
  });
  return { scene, clips: out, natural, height: height > 0 ? height : 0, clone };
}

const cache = new Map<number, Promise<StRigSource | null>>();

/* Làm nóng shader (D-018): stroll/index.ts gắn hàm biên dịch sẵn chương trình của cảnh nguồn theo đèn / sương / bóng của cảnh chính
   (rig.ts không import renderer để chạy được trong unit test). Chưa gắn, lỗi hoặc quá anim.warmMs: bỏ qua, nguồn vẫn dùng được */
let warm: ((o: THREE.Object3D) => Promise<unknown>) | null = null;
export function stRigSetWarm(fn: ((o: THREE.Object3D) => Promise<unknown>) | null): void { warm = fn; }
async function stRigWarm(o: THREE.Object3D): Promise<void> {
  if (!warm) return;
  let timer = 0;
  try { await Promise.race([warm(o), new Promise<void>((r) => { timer = setTimeout(r, A.warmMs) as unknown as number; })]); }
  catch { /* biên dịch trước lỗi: lần vẽ đầu tự biên dịch như cũ */ }
  finally { clearTimeout(timer); }
}

/* Nạp mô hình k (nhớ đệm). Không bao giờ ném / từ chối: lỗi → warn một lần, null */
export function stRigLoad(model: number): Promise<StRigSource | null> {
  let p = cache.get(model);
  if (p) return p;
  p = (async () => {
    try {
      const path = A.models[model];
      if (!path) throw new Error('không có mô hình số này');
      const [{ GLTFLoader }, SU] = await Promise.all([import('three/addons/loaders/GLTFLoader.js'), import('three/addons/utils/SkeletonUtils.js')]);
      const gltf = await new GLTFLoader().loadAsync(import.meta.env.BASE_URL + path);
      const speeds: Record<string, number> = {};
      const json = gltf.parser.json as { animations?: { name?: string; extras?: { speed?: number } }[] };   // AnimationClip không giữ extras: đọc từ JSON gốc
      for (const a of json.animations || []) if (a.name) speeds[a.name] = Number(a.extras?.speed) || 0;
      const src = stRigSource(gltf.scene, gltf.animations, speeds, Number(gltf.scene.userData?.height) || 0, SU.clone);
      await stRigWarm(src.scene);   // nguồn chỉ "sẵn sàng" sau khi shader skinning đã biên dịch: lần hiện đầu không khựng
      return src;
    } catch (e) {
      console.warn(`Đi dạo: không nạp được mô hình người ${model}, dùng hình khối`, e);
      return null;
    }
  })();
  cache.set(model, p);
  return p;
}

/* Một nhân vật đang diễn: bản sao của nguồn + mixer riêng */
export class StRig {
  readonly root: THREE.Object3D;
  readonly src: StRigSource;
  readonly mixer: THREE.AnimationMixer;
  readonly actions: THREE.AnimationAction[] = [];
  readonly w = new Float32Array(NC);    // trọng số đang dùng (đã làm mượt), tổng = 1
  rate = 1;                             // hệ số tua đoạn di chuyển đang dùng
  phase = 0;                            // pha chung 0–1 của walk / jog / sprint
  private readonly mix: StClipMix = { w: new Float32Array(NC), rate: 1, loco: false };
  private fresh = true;                 // lần pose đầu: đặt thẳng trọng số đích, không làm mượt
  private photo = false;                // khung trước đang ở dáng chụp ảnh

  constructor(src: StRigSource) {
    this.src = src;
    this.root = src.clone(src.scene);
    this.root.name = 'stroll-rig';
    this.mixer = new THREE.AnimationMixer(this.root);
    for (let i = 0; i < NC; i++) {
      const a = this.mixer.clipAction(src.clips[i]);
      if (i === ST_PHOTO) { a.setLoop(THREE.LoopOnce, 1); a.clampWhenFinished = true; }
      if (i >= ST_LOCO0 && i <= ST_LOCO1) a.timeScale = 0;   // thời gian do pha chung đặt
      a.enabled = false; a.setEffectiveWeight(0); a.play();
      this.actions.push(a);
    }
  }

  /* Mỗi khung: dáng + tốc độ mặt bằng (m/s) + dt (s) → trọng số, pha, mixer.update */
  pose(pose: number, speed: number, dt: number): void {
    const d = dt > 0 ? (dt < CONFIG.stroll.dtMax ? dt : CONFIG.stroll.dtMax) : 0;   // NaN / âm → 0
    const mix = this.mix, w = this.w, acts = this.actions, clips = this.src.clips;
    stClipMix(pose, speed, this.src.natural, mix);
    const toPhoto = mix.w[ST_PHOTO] === 1;
    if (toPhoto && !this.photo) acts[ST_PHOTO].reset();   // chuyển sang chụp ảnh: giơ máy lại từ đầu
    this.photo = toPhoto;
    const k = this.fresh || !(A.fade > 0) ? 1 : 1 - Math.exp(-d / A.fade);   // fade ≤ 0: chuyển tức thì (tránh 0/0 = NaN khi d = 0)
    this.fresh = false;
    for (let i = 0; i < NC; i++) w[i] += (mix.w[i] - w[i]) * k;
    if (mix.loco) this.rate = mix.rate;   // đang rời nhóm di chuyển: giữ nhịp cũ trong lúc mờ dần
    let lw = 0, dur = 0;
    for (let i = ST_LOCO0; i <= ST_LOCO1; i++) { lw += w[i]; dur += w[i] * clips[i].duration; }
    if (lw > 1e-4 && dur > 1e-6) {
      const p = this.phase + d * this.rate / (dur / lw);   // chu kỳ của hỗn hợp = trung bình thời lượng theo trọng số
      this.phase = p - Math.floor(p);
    }
    for (let i = 0; i < NC; i++) {
      const a = acts[i], on = w[i] > 1e-4;
      if (i >= ST_LOCO0 && i <= ST_LOCO1) a.time = this.phase * clips[i].duration;
      if (on !== a.enabled) a.enabled = on;   // đoạn không trọng số: mixer bỏ qua, không tính
      a.setEffectiveWeight(on ? w[i] : 0);
    }
    this.mixer.update(d);
  }

  /* Đặt lại như vừa tạo: lần pose kế đặt thẳng trọng số đích */
  reset(): void { this.fresh = true; this.photo = false; this.phase = 0; this.w.fill(0); }

  /* Gỡ khỏi nhóm, bỏ mixer, giải phóng skeleton riêng của bản sao (SkeletonUtils.clone tạo skeleton mới cho mỗi SkinnedMesh; renderer cấp boneTexture cho từng cái).
     geometry / texture / vật liệu thuộc nguồn dùng chung nên không dispose */
  dispose(): void {
    this.mixer.stopAllAction();
    this.mixer.uncacheRoot(this.root);
    this.root.removeFromParent();
    const seen = new Set<THREE.Skeleton>();
    this.root.traverse((o) => {
      const sk = (o as THREE.SkinnedMesh).isSkinnedMesh ? (o as THREE.SkinnedMesh).skeleton : null;
      if (sk && !seen.has(sk)) { seen.add(sk); sk.dispose(); }
    });
  }
}
/* ============================ Đi dạo: chọn và trộn đoạn chuyển động của nhân vật có xương (thuần) ============================
   Từ dáng (pose) và tốc độ mặt bằng (m/s) tính trọng số năm đoạn idle / walk / jog / sprint / photo và hệ số tua `rate` cho đoạn di chuyển.
   Thuần: không import three, không đụng DOM, không cấp phát (gọi mỗi khung cho từng nhân vật, D-018): kết quả ghi vào `out` do bên gọi giữ.
   - Di chuyển (pose 1, 2 và 3 khi còn tốc độ ngang): trộn theo tốc độ, walk (≤ walkTo) → jog (jogAt) → sprint (≥ sprintFrom), tuyến tính giữa các mốc; dáng đi / chạy chỉ cho biết đang di chuyển.
   - rate = tốc độ thật / tốc độ tự nhiên của đoạn trộn, kẹp [rateMin, rateMax]: chân chạm đất gần đúng không trượt.
   - Dáng lạ (khách bản cũ, số ngoài 0..4, NaN) và rơi không còn tốc độ ngang: đứng yên (idle). Khách bản cũ gửi dáng 3 khi nhảy; người đó hiện đứng yên. */
import { CONFIG } from '../../config';
import { exCharNorm } from '../multi/protocol';
import { ST_POSE_WALK, ST_POSE_RUN, ST_POSE_FALL, ST_POSE_PHOTO } from './motion';

export const ST_CLIPS = ['idle', 'walk', 'jog', 'sprint', 'photo'] as const;
export type StClip = typeof ST_CLIPS[number];

export interface StClipMix {
  w: Float32Array;   // 5 trọng số theo thứ tự ST_CLIPS, tổng = 1
  rate: number;      // hệ số tua đoạn di chuyển
  loco: boolean;     // đang di chuyển (walk / jog / sprint có trọng số)
}

const A = CONFIG.stroll.anim;

export function stClipMix(pose: number, speed: number, natural: ArrayLike<number>, out: StClipMix): void {
  const w = out.w, v = speed > 0 ? speed : 0;
  w[0] = 0; w[1] = 0; w[2] = 0; w[3] = 0; w[4] = 0;
  out.rate = 1; out.loco = false;
  if (pose === ST_POSE_PHOTO) { w[4] = 1; return; }
  const move = pose === ST_POSE_WALK || pose === ST_POSE_RUN || (pose === ST_POSE_FALL && v >= A.fallMin);
  if (!move) { w[0] = 1; return; }
  out.loco = true;
  if (v <= A.walkTo) w[1] = 1;
  else if (v < A.jogAt) { const t = (v - A.walkTo) / (A.jogAt - A.walkTo); w[1] = 1 - t; w[2] = t; }
  else if (v < A.sprintFrom) { const t = (v - A.jogAt) / (A.sprintFrom - A.jogAt); w[2] = 1 - t; w[3] = t; }
  else w[3] = 1;
  const nat = w[1] * natural[1] + w[2] * natural[2] + w[3] * natural[3];
  const r = nat > 1e-6 ? v / nat : 1;
  out.rate = r < A.rateMin ? A.rateMin : r > A.rateMax ? A.rateMax : r;
}

/* Mô hình của nhân vật người chơi chọn (0 nam, 1 nữ; giá trị lạ / không có = nam). Mình và người khác dùng chung hàm này:
   mô hình chỉ phụ thuộc lựa chọn của chủ nhân vật, không theo slot hay theo máy đang nhìn, nên mọi máy thấy cùng một người như nhau */
export function stCharModel(ch: unknown): number { return A.chars[exCharNorm(ch)]; }
/* ===== Đi dạo: nhân vật người chơi chọn ở sảnh (0 nam, 1 nữ) =====
   Lựa chọn nhớ ở localStorage (như tên, multi/lobby.ts) nên giữ qua xuất phát lại, kết nối lại và tải lại trang; bộ nhớ bị chặn thì chỉ giữ trong phiên trang.
   Giá trị lạ / chưa chọn: nam (exCharNorm). Mô hình ứng với nhân vật: stCharModel (anim.ts). Lựa chọn tới máy khác qua tin join (multi/session.ts) và walkers của lobby. */
import { exCharNorm } from '../multi/protocol';

const KEY = 'stChar';
let cur = -1;   // -1: chưa đọc bộ nhớ

export const stChar = {
  get(): number {
    if (cur < 0) { try { cur = exCharNorm(Number(localStorage.getItem(KEY))); } catch { cur = 0; } }
    return cur;
  },
  set(ch: number): void {
    cur = exCharNorm(ch);
    try { localStorage.setItem(KEY, String(cur)); } catch { /* bộ nhớ trình duyệt bị chặn (hoặc không có, trong test đơn vị) */ }
  }
};
/* ============================ Lái xe máy: người lái có xương (src/explore/bike/rider.ts) ============================
   Spec D-040 §6, §17.10 (tư thế ngồi = bảng góc khớp trong code + IK, không chạy lại gen:people).
   - Nhân vật: nguồn của Đi dạo (stroll/rig.ts stRigLoad, p0 nam / p3 nữ theo stCharModel), một bản sao (src.clone = SkeletonUtils.clone), KHÔNG AnimationMixer:
     mỗi khung xương về tư thế đứng chữ A của mô hình (PlBones.restore) rồi cộng góc. Hệ C = hệ gốc bản sao: +X trước mặt, +Y lên, +Z bên phải (trùng hệ thân xe).
   - Cây nút: neo `seat` của xe (đọc lại bike.anchors mỗi khung: neo đổi khi hình tạm đổi sang mô hình thật) → group 'bike-rider' → bản sao nhân vật
     (dời để xương Pelvis ở rider.seat so với đỉnh yên). Nhờ vậy người theo đủ yaw / pitch / nghiêng / giảm xóc của phần trên lò xo.
   - Mỗi khung: 1) bảng góc khớp (bkRiderPose): lưng cúi chia ba đốt, cổ, đầu, gập hông, gập gối, đùi xoay ra, xương đòn; cộng lò xo phản ứng:
     lưng ngả theo gia tốc dọc, đầu bù (1 − headLean) độ nghiêng, đầu quay theo góc lái; 2) IK chân: plTwoBone hông → gối → cổ chân tới neo foot_l / foot_r
     (+ rider.ankle), đùi và cẳng chân xoay cung ngắn nhất từ tư thế bảng (giữ độ xoắn của bảng), bàn chân về hướng lúc đứng (phẳng trên sàn);
     3) IK tay: PlBones.ik của người treo dù với bộ số rider.arm / rider.finger, điểm nắm tới neo grip_l / grip_r (con của cổ lái: bẻ lái thì tay theo).
   - Mũ bảo hiểm nửa đầu: nửa khối cầu (SphereGeometry cắt nửa) gắn xương đầu, vật liệu MeshStandardMaterial màu theo đỉnh = cùng chương trình với hình tạm
     của xe (model.ts bkTempMaterial, đã làm nóng) nên không thêm program. Lớp 1, không bóng như xe.
   - Lệnh vẽ: nhân vật Rocketbox là 1 SkinnedMesh 3 primitive (thân, đầu, mảnh alpha) = 3 lệnh, như nhân vật đi dạo; mũ 1 lệnh.
   - Góc nhìn thứ nhất: xương đầu thu về scale ≈ 0 (mũ là con của xương đầu nên ẩn theo); thân, tay giữ.
   - Chưa có mô hình xe thật (bike.real = false): người ẩn, không tính IK (hình tạm của xe đã có người khối; hai người chồng nhau thì sai).
   Không cấp phát mỗi khung (D-018). */
import * as THREE from 'three';
import { CONFIG } from '../../config';
import { plTwoBone } from '../pilot/ik';
import { PlBones } from '../pilot/bones';
import { stRigLoad, type StRigSource } from '../stroll/rig';
import { stCharModel } from '../stroll/anim';
import type { BkBike } from './model';

export interface BkRiderSig { lean: number; acc: number; susF: number; susR: number; steer: number }   // lean rad (trái +), acc m/s² gia tốc dọc, susF / susR m lún giảm xóc, steer rad (trái +)

const RC = CONFIG.bike.rider;
const TAU = Math.PI * 2;
const A_REF = (50 / 3.6) / CONFIG.bike.perf.t50;   // m/s² — gia tốc khi vặn hết ga dưới 50 km/h (motion.ts A0)

/* ===== Bảng góc khớp tư thế ngồi nền (rad), thứ tự cố định ===== */
export const BK_POSE = { spine: 0, neck: 1, head: 2, hip: 3, knee: 4, legSplit: 5, ankle: 6, clavicle: 7, clavicleFore: 8 } as const;
export const BK_POSE_N = 9;
export function bkRiderPose(out: Float32Array): void {
  const P = RC.pose;
  out[BK_POSE.spine] = P.spine; out[BK_POSE.neck] = P.neck; out[BK_POSE.head] = P.head;
  out[BK_POSE.hip] = P.hip; out[BK_POSE.knee] = P.knee; out[BK_POSE.legSplit] = P.legSplit; out[BK_POSE.ankle] = P.ankle;
  out[BK_POSE.clavicle] = P.clavicle; out[BK_POSE.clavicleFore] = P.clavicleFore;
}

/* Nạp nhân vật ch (0 nam / 1 nữ) — chung bộ nạp, bộ đệm và làm nóng với Đi dạo. Không bao giờ từ chối: lỗi → null */
export function bkRiderLoad(ch: number): Promise<StRigSource | null> { return stRigLoad(stCharModel(ch)); }

const AZ = new THREE.Vector3(0, 0, 1);
const _inv = new THREE.Matrix4(), _q = new THREE.Quaternion(), _q2 = new THREE.Quaternion(), _qa = new THREE.Quaternion(), _qb = new THREE.Quaternion(), _qc = new THREE.Quaternion();
const _h = new THREE.Vector3(), _k = new THREE.Vector3(), _a = new THREE.Vector3(), _d = new THREE.Vector3(), _d2 = new THREE.Vector3();
const _hip = [0, 0, 0], _tgt = [0, 0, 0], _pole = [0, 0, 0], _knee = [0, 0, 0], _end = [0, 0, 0];
const _tL = new THREE.Vector3(), _tR = new THREE.Vector3();

/* Hình học mũ: nửa khối cầu (vỏ trên), màu theo đỉnh */
function bkHelmetGeometry(): THREE.BufferGeometry {
  const H = RC.helmet, g = new THREE.SphereGeometry(H.r, 20, 8, 0, TAU, 0, Math.PI / 2);
  const c = new THREE.Color(H.color), n = g.getAttribute('position').count, col = new Float32Array(n * 3);
  for (let i = 0; i < n; i++) { col[i * 3] = c.r; col[i * 3 + 1] = c.g; col[i * 3 + 2] = c.b; }
  g.setAttribute('color', new THREE.BufferAttribute(col, 3));
  return g;
}

export class BkRider {
  readonly group = new THREE.Group();
  readonly root: THREE.Object3D;
  readonly bones: PlBones;
  readonly helmet: THREE.Mesh;
  private readonly pose = new Float32Array(BK_POSE_N);
  private readonly feet: THREE.Object3D[];
  private readonly legL1 = [0, 0]; private readonly legL2 = [0, 0];   // m — đùi, cẳng chân
  private readonly footRest = [new THREE.Quaternion(), new THREE.Quaternion()];   // hướng bàn chân trong hệ C lúc đứng (phẳng)
  private readonly footT = [new THREE.Vector3(), new THREE.Vector3()];   // đích cổ chân, hệ C (cho debug)
  private readonly sx = new Float64Array(3); private readonly sv = new Float64Array(3);   // lò xo: lưng chúi, đầu bù nghiêng, đầu quay
  private disposed = false;

  constructor(src: StRigSource) {
    this.group.name = 'bike-rider';
    this.root = src.clone(src.scene);
    this.root.name = 'bike-rider-body';
    this.group.add(this.root);
    const b = this.bones = new PlBones(this.root);   // thiếu xương thì ném (index.ts bắt)
    if (!b.foot[0] || !b.foot[1]) throw new Error('thiếu xương bàn chân');
    this.feet = [b.foot[0], b.foot[1]];
    /* số đo ở tư thế đứng: tay (PlBones.measure với bộ số của xe máy), chân, hướng bàn chân, chỗ xương hông */
    b.measure(RC.arm);
    b.updateMatrices();
    for (let i = 0; i < 2; i++) {
      b.pC(b.thigh[i], _h); b.pC(b.calf[i], _k); b.pC(this.feet[i], _a);
      this.legL1[i] = Math.max(0.05, _h.distanceTo(_k)); this.legL2[i] = Math.max(0.05, _k.distanceTo(_a));
      b.qC(this.feet[i], this.footRest[i]);
    }
    b.pC(b.pelvis, _h);
    this.root.position.set(RC.seat.fore - _h.x, RC.seat.up - _h.y, -_h.z);
    /* mũ: trục theo hệ C lúc đứng thẳng, tâm trên xương đầu; con của xương đầu */
    const H = RC.helmet;
    this.helmet = new THREE.Mesh(bkHelmetGeometry(), new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.45, metalness: 0.1 }));
    this.helmet.name = 'bike-helmet';
    b.qC(b.head, _q).invert();
    const hs = _h.setFromMatrixScale(_inv.copy(this.root.matrixWorld).invert().multiply(b.head.matrixWorld)).x || 1;   // tỉ lệ xương đầu so với hệ C (Rocketbox: Bip01 scale 0,01, đơn vị cm)
    this.helmet.quaternion.copy(_q).multiply(_qa.setFromAxisAngle(AZ, H.pitch));   // trục mũ = hệ C ngửa pitch quanh trục ngang
    this.helmet.position.set(H.fore, H.up, 0).applyQuaternion(_q).divideScalar(hs);
    this.helmet.scale.set(H.scale[0] / hs, H.scale[1] / hs, H.scale[2] / hs);
    b.head.add(this.helmet);
    this.group.traverse((o) => {
      o.layers.set(1);
      const m = o as THREE.Mesh;
      if (m.isMesh) { m.castShadow = false; m.receiveShadow = false; m.frustumCulled = false; }
    });
    bkRiderPose(this.pose);
    this.group.visible = false;
  }

  /* Lò xo bậc hai ba kênh tới đích, bước con ≤ 1/120 s (ổn định với mọi dt đã kẹp) */
  private spring(sig: BkRiderSig, d: number): void {
    const acc = Number.isFinite(sig.acc) ? sig.acc : 0, lean = Number.isFinite(sig.lean) ? sig.lean : 0, steer = Number.isFinite(sig.steer) ? sig.steer : 0;
    const t0 = acc >= 0 ? -RC.accLean * Math.min(1, acc / A_REF) : RC.brakeLean * Math.min(1, -acc / CONFIG.bike.perf.hardBrake);
    const t1 = lean * (1 - RC.headLean), t2 = steer * RC.steerLook;
    if (!(d > 0)) return;
    const w = TAU * RC.hz, z = RC.damp, n = Math.ceil(d * 120), h = d / n, x = this.sx, v = this.sv;
    for (let s = 0; s < n; s++) {
      v[0] += (w * w * (t0 - x[0]) - 2 * z * w * v[0]) * h; x[0] += v[0] * h;
      v[1] += (w * w * (t1 - x[1]) - 2 * z * w * v[1]) * h; x[1] += v[1] * h;
      v[2] += (w * w * (t2 - x[2]) - 2 * z * w * v[2]) * h; x[2] += v[2] * h;
    }
  }

  /* Xoay xương o thêm R (hệ C) quanh khớp của nó (như PlBones.rotC) */
  private rotC(o: THREE.Object3D, R: THREE.Quaternion): void {
    this.bones.qC(o.parent, _q2);
    o.quaternion.premultiply(_q.copy(_q2).invert().multiply(R).multiply(_q2));
  }

  /* Vị trí neo trong hệ C (ma trận thế giới đã cập nhật; _inv = nghịch đảo ma trận gốc bản sao) */
  private toC(o: THREE.Object3D, out: THREE.Vector3): THREE.Vector3 { return out.setFromMatrixPosition(o.matrixWorld).applyMatrix4(_inv); }

  update(bike: BkBike, sig: BkRiderSig, dt: number): void {
    if (this.disposed) return;
    if (!bike.real) { this.group.visible = false; return; }
    const an = bike.anchors, b = this.bones, P = this.pose, B = BK_POSE;
    if (this.group.parent !== an.seat) an.seat.add(this.group);
    this.group.visible = true;
    const d = dt > 0 && Number.isFinite(dt) ? Math.min(dt, RC.dtMax) : 0;
    this.spring(sig, d);
    const x = this.sx;
    /* 1) bảng góc khớp + phản ứng (rotE: Euler YZX trong hệ C; quay âm quanh +Z = cúi trước; quay dương quanh +X = nghiêng phải; quay dương quanh +Y = quay trái) */
    b.restore();
    const k = 1 / b.spines.length;
    for (const s of b.spines) b.rotE(s, 0, 0, -(P[B.spine] + x[0]) * k);
    b.rotE(b.neck, 0, 0, -P[B.neck]);
    b.rotE(b.head, x[1], x[2], -P[B.head]);
    for (let i = 0; i < 2; i++) {
      const side = i ? 1 : -1;
      b.rotE(b.thigh[i], 0, -side * P[B.legSplit], P[B.hip]);
      b.rotE(b.calf[i], 0, 0, -P[B.knee]);
    }
    for (const a of b.arms) b.rotE(a.clav, -a.side * P[B.clavicle], 0, P[B.clavicleFore]);
    /* 2) chân */
    bike.group.updateMatrixWorld(true);
    b.updateMatrices();
    _inv.copy(this.root.matrixWorld).invert();
    const LP = RC.legPole, AK = RC.ankle;
    for (let i = 0; i < 2; i++) {
      const side = i ? 1 : -1, th = b.thigh[i], ca = b.calf[i], ft = this.feet[i], T = this.footT[i];
      this.toC(i ? an.footR : an.footL, T);
      T.x -= AK.back; T.y += AK.up;
      b.pC(th, _h); b.pC(ca, _k); b.pC(ft, _a);
      _hip[0] = _h.x; _hip[1] = _h.y; _hip[2] = _h.z;
      _tgt[0] = T.x; _tgt[1] = T.y; _tgt[2] = T.z;
      _pole[0] = _h.x + LP[0]; _pole[1] = _h.y + LP[1]; _pole[2] = _h.z + side * LP[2];
      plTwoBone(_hip, this.legL1[i], this.legL2[i], _tgt, _pole, _knee, _end);
      /* đùi: cung ngắn nhất từ hướng hiện tại (bảng) tới hướng hông → gối mới */
      _d.copy(_k).sub(_h).normalize(); _d2.set(_knee[0] - _h.x, _knee[1] - _h.y, _knee[2] - _h.z).normalize();
      _qa.setFromUnitVectors(_d, _d2);
      this.rotC(th, _qa);
      /* cẳng chân: hướng cũ (đã quay theo đùi) → gối → cổ chân mới */
      _d.copy(_a).sub(_k).normalize().applyQuaternion(_qa);
      _d2.set(_end[0] - _knee[0], _end[1] - _knee[1], _end[2] - _knee[2]).normalize();
      _qb.setFromUnitVectors(_d, _d2);
      this.rotC(ca, _qb);
      /* bàn chân: hướng lúc đứng (phẳng) + góc bảng quanh trục ngang */
      b.qC(ca, _q2).invert();
      ft.quaternion.copy(_q2).multiply(_qc.setFromAxisAngle(AZ, -P[B.ankle]).multiply(this.footRest[i]));
    }
    /* 3) tay */
    b.updateMatrices();
    this.toC(an.gripL, _tL); this.toC(an.gripR, _tR);
    b.ik(b.arms[0], _tL, RC.arm, RC.finger);
    b.ik(b.arms[1], _tR, RC.arm, RC.finger);
  }

  /* Góc nhìn thứ nhất: thu xương đầu (và mũ) về ≈ 0 */
  setFirstPerson(on: boolean): void {
    this.bones.head.scale.setScalar(on ? 1e-4 : 1);
  }

  /* Mắt trong hệ của nút frame (camera góc thứ nhất đo một lần ở tư thế ngồi nền: index.ts riderEye): điểm giữa hai xương mắt Bip01_LEye / REye
     (Rocketbox có), trả true; thiếu thì vị trí xương đầu, trả false (người gọi cộng cam1.headEye) */
  eyeLocal(frame: THREE.Object3D, out: THREE.Vector3): boolean {
    frame.updateWorldMatrix(true, true);
    const l = this.root.getObjectByName('Bip01_LEye') ?? this.root.getObjectByName('Bip01 LEye'), r = this.root.getObjectByName('Bip01_REye') ?? this.root.getObjectByName('Bip01 REye');
    if (l && r) out.setFromMatrixPosition(l.matrixWorld).add(_a.setFromMatrixPosition(r.matrixWorld)).multiplyScalar(0.5);
    else out.setFromMatrixPosition(this.bones.head.matrixWorld);
    frame.worldToLocal(out);
    return !!(l && r);
  }

  /* m — khoảng cách điểm nắm – tay nắm (hai tay), cổ chân – đích cổ chân trên sàn (hai chân), sau update gần nhất */
  debug(): { handL: number; handR: number; footL: number; footR: number } {
    const b = this.bones;
    b.updateMatrices();
    _inv.copy(this.root.matrixWorld).invert();
    const f = (i: number): number => b.pC(this.feet[i], new THREE.Vector3()).distanceTo(this.footT[i]);
    return { handL: b.handErr(0), handR: b.handErr(1), footL: f(0), footR: f(1) };
  }

  /* Gỡ khỏi xe, giải phóng skeleton riêng của bản sao, hình học / vật liệu mũ. Hình học / texture / vật liệu nhân vật thuộc nguồn dùng chung nên giữ */
  dispose(): void {
    if (this.disposed) return;
    this.disposed = true;
    this.group.removeFromParent();
    const seen = new Set<THREE.Skeleton>();
    this.root.traverse((o) => {
      const sk = (o as THREE.SkinnedMesh).isSkinnedMesh ? (o as THREE.SkinnedMesh).skeleton : null;
      if (sk && !seen.has(sk)) { seen.add(sk); sk.dispose(); }
    });
    this.helmet.geometry.dispose();
    (this.helmet.material as THREE.Material).dispose();
  }
}

