<p class="subtitle">Phác thảo mặt trước, nam (trái) và nữ (phải) của mỗi hướng. Mô hình thật là Rocketbox p0 / p3 vẽ lại texture, nên dáng người giữ nguyên; ở đây chỉ để so màu, mảng, biểu tượng và mặt nạ. Cả ba đều tránh các nét nhận diện của Người Nhện: không lưới mạng nhện, không hình con nhện, không cặp mắt trắng lớn viền đen, không bố cục "thân đỏ – hông xanh".</p>

<div class="cards" id="cards"></div>

<script>
(function(){
  /* Mỗi hướng: màu nền, màu mảng, màu nhấn, kiểu mảng, biểu tượng, mặt nạ */
  const C = [
    { id:'rong', name:'A. Rồng Sông Hàn',
      desc:'Bộ đồ đỏ thẫm, vai, cẳng tay và ủng xanh đậm. Ngực có vân vảy vàng hình chữ V, biểu tượng là vòm Cầu Rồng (đường cong uốn lượn). Mặt nạ kín, một dải kính vàng ngang mắt.',
      base:'#b3202a', panel:'#173a7a', acc:'#f2b632', motif:'scales', emblem:'arch', visor:'band' },
    { id:'song', name:'B. Sóng Biển Đà Nẵng',
      desc:'Bộ đồ xanh hải quân, hai dải sóng đỏ chéo từ vai xuống hông đối diện, đường viền trắng mảnh. Biểu tượng là vòng tròn ba con sóng. Mắt hai kính hổ phách góc cạnh, nhỏ.',
      base:'#1b2f6b', panel:'#c62f2f', acc:'#f4f1e8', motif:'waves', emblem:'waves', visor:'angular' },
    { id:'cap', name:'C. Dây Cầu Phát Sáng',
      desc:'Bộ đồ xanh lam, mảng đỏ ở ngực và đùi, các đường chỉ thẳng xòe từ cổ áo như dây văng cầu Thuận Phước. Biểu tượng hình thoi (tháp cầu). Kính chữ T kiểu mũ bảo hiểm. Ban đêm các đường chỉ có thể sáng (emissive, tùy chọn).',
      base:'#2453a6', panel:'#b8262e', acc:'#7fe3ff', motif:'cables', emblem:'diamond', visor:'tee' }
  ];
  function fig(c, f){
    const sh = f ? 26 : 32, hip = f ? 24 : 20, w = 100, cx = 50;
    const L = cx - sh, R = cx + sh;
    let s = `<svg viewBox="0 0 100 210" width="120" height="252" xmlns="http://www.w3.org/2000/svg">`;
