    s += `<path d="M${cx-hip} 110 L${cx-4} 110 L${cx-6} 196 L${cx-hip+2} 196 Z" fill="${c.base}"/>`;
    s += `<path d="M${cx+4} 110 L${cx+hip} 110 L${cx+hip-2} 196 L${cx+6} 196 Z" fill="${c.base}"/>`;
