    s += `<path d="M${L} 46 L${L+9} 46 L${L+4} 112 L${L-6} 112 Z" fill="${c.base}"/>`;
    s += `<path d="M${R-9} 46 L${R} 46 L${R+6} 112 L${R-4} 112 Z" fill="${c.base}"/>`;
    if (c.motif==='scales') {
      s += `<path d="M${L+1} 80 L${L+7} 80 L${L+4} 112 L${L-6} 112 Z" fill="${c.panel}"/>`;
      s += `<path d="M${R-7} 80 L${R-1} 80 L${R+6} 112 L${R-4} 112 Z" fill="${c.panel}"/>`;
    }
    /* thân */
    s += `<path d="M${L} 44 Q${cx} 36 ${R} 44 L${cx+hip} 112 L${cx-hip} 112 Z" fill="${c.base}"/>`;
    /* mảng theo hướng */
    if (c.motif==='scales') {
      s += `<path d="M${L} 44 Q${L+6} 40 ${L+12} 41 L${L+8} 58 L${L+1} 56 Z" fill="${c.panel}"/>`;
      s += `<path d="M${R} 44 Q${R-6} 40 ${R-12} 41 L${R-8} 58 L${R-1} 56 Z" fill="${c.panel}"/>`;
      for (let i=0;i<4;i++) s += `<path d="M${cx-14+i*2} ${66+i*7} L${cx} ${74+i*7} L${cx+14-i*2} ${66+i*7}" fill="none" stroke="${c.acc}" stroke-width="1.6"/>`;
