      s += `<path d="M${cx-hip+1} 122 L${cx-6} 122 L${cx-7} 150 L${cx-hip+2} 150 Z" fill="${c.panel}"/>`;
      s += `<path d="M${cx+6} 122 L${cx+hip-1} 122 L${cx+hip-2} 150 L${cx+7} 150 Z" fill="${c.panel}"/>`;
