    if (c.emblem==='waves') { s += `<circle cx="${cx}" cy="60" r="8" fill="${c.base}" stroke="${c.acc}" stroke-width="1.2"/>`; for (let k=0;k<3;k++) s += `<path d="M${cx-6} ${57+k*3} q3 -2 6 0 t6 0" fill="none" stroke="${c.acc}" stroke-width="0.9"/>`; }
    if (c.emblem==='diamond') s += `<path d="M${cx} 50 L${cx+6} 60 L${cx} 70 L${cx-6} 60 Z" fill="${c.acc}"/>`;
    /* đai lưng */
    s += `<rect x="${cx-hip}" y="104" width="${hip*2}" height="6" fill="${c.motif==='waves'?c.acc:c.panel}" opacity="0.9"/>`;
    /* cổ + đầu (mặt nạ kín) */
    s += `<rect x="${cx-5}" y="32" width="10" height="8" fill="${c.base}"/>`;
    s += `<ellipse cx="${cx}" cy="20" rx="${f?11:12}" ry="15" fill="${c.motif==='scales'?c.base:c.base}"/>`;
