    if (c.visor==='tee') { s += `<rect x="${cx-10}" y="14" width="20" height="4" fill="${c.acc}"/><rect x="${cx-1.5}" y="14" width="3" height="14" fill="${c.acc}"/>`; }
    if (c.motif==='scales') s += `<path d="M${cx-12} 12 Q${cx} 4 ${cx+12} 12" fill="none" stroke="${c.panel}" stroke-width="3"/>`;
    s += `</svg>`;
    return s;
  }
  const el = document.getElementById('cards');
  el.innerHTML = C.map(c => `
    <div class="card" data-choice="${c.id}" onclick="toggleSelect(this)">
      <div class="card-image" style="display:flex;justify-content:center;gap:18px;background:#e9eef5;padding:12px">${fig(c,false)}${fig(c,true)}</div>
      <div class="card-body"><h3>${c.name}</h3><p>${c.desc}</p></div>
    </div>`).join('');
})();
</script>
